#include <stdio.h>
int main() {
    long long val, b;
    if (scanf("%lld %lld", &val, &b) != 2) return 0;
    if (val == 0) { printf("0\n"); return 0; }
    char digits[100]; int idx = 0;
    while (val > 0) { digits[idx++] = (val % b) + '0'; val /= b; }
    for (int i = idx - 1; i >= 0; i--) putchar(digits[i]);
    putchar('\n');
    return 0;
}

