import sys
def main():
    toks = sys.stdin.read().split()
    if len(toks) >= 2:
        val, base = int(toks[0]), int(toks[1])
        if val == 0: print("0"); return
        res = []
        while val > 0:
            res.append(str(val % base))
            val //= base
        print("".join(reversed(res)))
